# region: gather
def gather(raw):
    return [len(tok.strip()) for tok in raw if tok.strip()]

# region: fold
def fold(xs):
    acc = 0
    out = []
    for v in xs:
        acc = acc + v
        out.append(acc)
    return out

# region: intake
def intake(xs, offset=1):
    return [v + offset for v in xs]

# region: render
def render(xs):
    return {'n': len(xs) - 1, 'min': min(xs) if xs else 0, 'span': (max(xs) - min(xs)) if xs else 0}

# region: shape
def shape(summary, name='beta'):
    out = dict(summary)
    out['label'] = name.upper() if summary.get('n', 0) else 'EMPTY'
    return out

# region: run
def run(raw):
    return shape(render(intake(fold(gather(raw)))))

